# RW2DM_LOCKS: LockSwap, IsolateLock, UnisolateLock, UnlockSelected. The script rw2dm_locks_script.txt is generated by rw2dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW2_LOCKS_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW2_LOCKS_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw2dm_locks_script.txt" 2>&1)" || { echo "$RW2_LOCKS_OUT" | tail -40; echo "FAIL RW2DM_LOCKS_run: script exited non-zero"; fail=1; RW2_LOCKS_OUT=""; }
else
  RW2_LOCKS_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw2dm_locks_script.txt" 2>&1)" || { echo "$RW2_LOCKS_OUT" | tail -40; echo "FAIL RW2DM_LOCKS_run: script exited non-zero"; fail=1; RW2_LOCKS_OUT=""; }
fi
rw2_locks_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_LOCKS_OUT"; }
# rw2_locks_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw2_locks_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw2_locks_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW2DM_LOCKS_$name: $desc (objects: $got)"
  else echo "FAIL RW2DM_LOCKS_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw2_locks_state lockswap "1:point:Default 2:curve:Default" "LockSwap with 1 and 2 locked locks 3 and 4 and unlocks 1 and 2: SelAll reaches 1 and 2" 
rw2_locks_state lockswap2 "3:surface:Default 4:polysurface:Default" "a second LockSwap swaps back: 1 and 2 locked, SelAll reaches 3 and 4" 
rw2_locks_state lockswap_none "-" "LockSwap with nothing locked locks everything: SelAll reaches no object" 
rw2_locks_state unlock_for_isolate "1:point:Default 2:curve:Default 3:surface:Default 4:polysurface:Default" "Unlock restores all four" 
rw2_locks_state isolatelock "2:curve:Default" "IsolateLock of 2 locks every other visible object: SelAll reaches only 2" "IsolateLock: 3 object\(s\) locked"
rw2_locks_state unisolatelock "1:point:Default 2:curve:Default 3:surface:Default 4:polysurface:Default" "UnisolateLock unlocks what IsolateLock locked: all four selectable again" "UnisolateLock: 3 object\(s\) unlocked"
rw2_locks_state isolatelock_prelocked "2:curve:Default 3:surface:Default 4:polysurface:Default" "an object locked BEFORE IsolateLock (1) stays locked after UnisolateLock: IsolateLock of 2 then UnisolateLock leaves 2, 3 and 4 selectable" "UnisolateLock: 2 object\(s\) unlocked"
rw2_locks_state unlockselected "1:point:Default" "UnlockSelected unlocks the locked object 1 and selects it (it is listed as the selection)" 
rw2_locks_state unlockselected_two "2:curve:Default 3:surface:Default" "with 2 and 3 locked, UnlockSelected unlocks and selects exactly 2 and 3" 
